const assetPathPrefix = "https://www.figma.com/api/mcp/asset/99b92b14-5c7b-4c0b-85dc-50b17487e3bd";
const imgIconsPlaceholder = `${assetPathPrefix}/cf70e.svg`;
const imgIconsSolidIcSolarEyeBold = `${assetPathPrefix}/aa597.svg`;
const imgStartAdornment = `${assetPathPrefix}/112ca.svg`;
const imgIconsGenericInfo = `${assetPathPrefix}/056df.svg`;

type TextFieldProps = {
  className?: string;
  endAdornment?: boolean;
  endAdornment1?: React.ReactNode | null;
  helpText?: boolean;
  label?: boolean;
  selectArrow?: boolean;
  size?: "LG";
  startAdornment?: boolean;
  startAdornment1?: React.ReactNode | null;
  state?: "Enabled";
  value?: "False";
};

function TextField({ className, endAdornment = false, endAdornment1 = null, helpText = false, label = true, selectArrow = false, size = "LG", startAdornment = false, startAdornment1 = null, state = "Enabled", value = "False" }: TextFieldProps) {
  return (
    <div className={className || "content-stretch flex flex-col items-start relative w-[320px]"} data-node-id="196:62341">
      <div className="bg-white border border-[var(--components\/textfield\/outline,#c4cdd5)] border-solid content-stretch flex h-[54px] items-center px-[var(--textfield\/\[outlined\]--px,14px)] relative rounded-[var(--textfield\/\[outlined\]--radius,8px)] shrink-0 w-full" data-node-id="1670:167088" data-name="wrap">
        {startAdornment && (
          <div className="content-stretch flex items-center pr-[var(--textfield\/\[start-adornment\]--mr,8px)] relative shrink-0" data-node-id="2832:223717" data-name="start adornment">
            {startAdornment &&
              (startAdornment1 || (
                <div className="content-stretch flex items-center justify-center relative shrink-0 size-[24px]" data-node-id="1671:105318" data-name="✳️ start adornment">
                  <div className="relative shrink-0 size-[24px]" data-node-id="I1671:105318;60:85910" data-name="icons/placeholder">
                    <img alt="" className="absolute block inset-0 max-w-none size-full" src={imgIconsPlaceholder} />
                  </div>
                </div>
              ))}
          </div>
        )}
        {label && (
          <p className="[word-break:break-word] flex-[1_0_0] font-['Segoe_UI:Regular'] leading-[22px] min-w-px not-italic overflow-hidden relative text-[14px] text-[color:var(--text\/disabled,#919eab)] text-ellipsis whitespace-nowrap" data-node-id="1670:167091">
            Label
          </p>
        )}
        <div className="-translate-y-1/2 absolute content-stretch flex h-[40px] items-center justify-center right-[-1px] top-1/2" data-node-id="2882:339154" data-name="end adornment">
          {endAdornment &&
            (endAdornment1 || (
              <div className="content-stretch flex items-center justify-center relative rounded-[var(--icon-button\/radius,500px)] shrink-0 size-[40px]" data-node-id="1774:138265" data-name="✳️ end adornment">
                <div className="relative shrink-0 size-[24px]" data-node-id="I1774:138265;1670:141825" data-name="icons/placeholder">
                  <img alt="" className="absolute block inset-0 max-w-none size-full" src={imgIconsSolidIcSolarEyeBold} />
                </div>
              </div>
            ))}
        </div>
        {selectArrow && (
          <div className="-translate-y-1/2 absolute content-stretch flex items-center pr-[var(--textfield\/\[select-arrow\]--mr,10px)] right-[-1px] top-1/2" data-node-id="2832:232680" data-name="select arrow">
            {selectArrow && (
              <div className="relative shrink-0 size-[20px]" data-node-id="1774:147425" data-name="start adornment">
                <img alt="" className="absolute block inset-0 max-w-none size-full" src={imgStartAdornment} />
              </div>
            )}
          </div>
        )}
      </div>
      {helpText && (
        <div className="content-stretch flex gap-[var(--form-helper-text\/spacing,4px)] items-center pl-[var(--form-helper-text\/pl,12px)] pt-[var(--form-helper-text\/pt,8px)] relative shrink-0 w-full" data-node-id="1670:167099" data-name="✳️ helper text">
          <div className="relative shrink-0 size-[16px]" data-node-id="I1670:167099;1670:166664" data-name="icons/generic/info">
            <img alt="" className="absolute block inset-0 max-w-none size-full" src={imgIconsGenericInfo} />
          </div>
          <p className="[word-break:break-word] flex-[1_0_0] font-['Segoe_UI:Regular'] leading-[18px] min-w-px not-italic relative text-[12px] text-[color:var(--text\/secondary,#637381)]" data-node-id="I1670:167099;0:14453">
            Caption text, description, notification
          </p>
        </div>
      )}
    </div>
  );
}
